import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import UploadBox from './components/UploadBox';
import AgentDescription from './components/AgentDescription';
import SARNarrative from './components/SARNarrative';
import ProfileIcon from './components/ProfileIcon';
import AgentDashboard from './components/AgentDashboard';
import './App.css';

function App() {
  // State for selected agent and its information
  const [selectedAgent, setSelectedAgent] = useState(null);
  const [agentInfo, setAgentInfo] = useState({ 
    description: '', 
    narrative: '',
    status: {
      isActive: false,       // Tracks if agent is running
      lastActive: null,      // Last activity timestamp
      progress: 0,           // Completion percentage (0-100)
      lastLog: '',           // Most recent log message
      tasks: []              // Upcoming tasks
    }
  });
  const [uploadedFile, setUploadedFile] = useState(null);
  const [agentsStatus, setAgentsStatus] = useState({});

  // Fetch agent statuses periodically
  useEffect(() => {
    const fetchAgentStatuses = async () => {
      try {
        const response = await fetch('http://localhost:5003/agent-status');
        const data = await response.json();
        setAgentsStatus(data);

        // Update current agent if selected
        if (selectedAgent && data[selectedAgent]) {
          setAgentInfo(prev => ({
            ...prev,
            status: {
              ...prev.status,
              ...data[selectedAgent]
            }
          }));
        }
      } catch (error) {
        console.error('Agent status fetch error:', error);
      }
    };

    fetchAgentStatuses();
    const interval = setInterval(fetchAgentStatuses, 30000); // Refresh every 30 sec

    return () => clearInterval(interval);
  }, [selectedAgent]);

  // Handle agent selection
  const handleAgentSelect = async (agentName) => {
    try {
      const res = await fetch(`http://localhost:5003/agent/${encodeURIComponent(agentName)}`);
      const data = await res.json();

      setSelectedAgent(agentName);
      setAgentInfo({
        description: data.description || '',
        narrative: data.narrative || '',
        status: {
          isActive: data.status?.isActive || false,
          lastActive: data.status?.lastActive || 'Never active',
          progress: data.status?.progress || 0,
          lastLog: data.status?.lastLog || 'No logs available',
          tasks: data.status?.tasks || ['Initialize agent', 'Load configuration']
        }
      });

      // Special handling for migration agent
      if (agentName === "Migration Execution & Oversight Agents" && uploadedFile) {
        await handleMigration(agentName);
      }
    } catch (error) {
      console.error('Agent data fetch failed:', error);
      alert('Failed to load agent data');
    }
  };

  // Handle migration process
  const handleMigration = async (agentName) => {
    try {
      const migrationRes = await fetch('http://localhost:5003/migrate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ filename: `uploads/${uploadedFile}` }),
      });
      const migrationData = await migrationRes.json();
      alert(migrationData.message || migrationData.error);
    } catch (error) {
      console.error('Migration failed:', error);
      alert('Migration process error');
    }
  };

  // Control agent start/stop
  const handleAgentControl = async (action) => {
    if (!selectedAgent) return;

    try {
      const response = await fetch('http://localhost:5003/agent-control', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          agent: selectedAgent,
          action: action  // 'start' or 'stop'
        })
      });

      const result = await response.json();
      if (result.success) {
        setAgentInfo(prev => ({
          ...prev,
          status: {
            ...prev.status,
            isActive: action === 'start',
            lastActive: new Date().toLocaleString()
          }
        }));
      } else {
        alert(`Action failed: ${result.error}`);
      }
    } catch (error) {
      console.error('Agent control error:', error);
      alert('Control command failed');
    }
  };

  return (
    <div className="app">
      {/* Left sidebar for agent selection */}
      <Sidebar onAgentClick={handleAgentSelect} />

      {/* Main content area */}
      <main className="main-section">
        {/* Top bar with upload and profile */}
        <div className="top-bar">
          <div className="left-section">
            <UploadBox onUploadSuccess={setUploadedFile} />
          </div>
          <ProfileIcon />
        </div>

        {/* Three-column content layout */}
        <div className="content-area">
          {/* Left column - Detailed description */}
          <div className="left-content">
            <AgentDescription 
              description={agentInfo.description} 
              agentName={selectedAgent}
            />
          </div>

          {/* Middle column - Dashboard */}
          <AgentDashboard 
            agent={selectedAgent}
            status={agentInfo.status}
            onControl={handleAgentControl}
          />

          {/* Right column - SAR Narrative */}
          <SARNarrative
            header={selectedAgent || 'System Summary'}
            narrative={agentInfo.narrative}
          />
        </div>
      </main>
    </div>
  );
}

export default App;
